{"code":"import json
import pandas as pd
import numpy as np

with open('evaluations.json') as f:
    evals = json.load(f)

cols = ['soy protein isolate', 'mushrooms', 'sunflower oil', 'breadcrumbs', 'coconut oil', 'onion', 'potato starch', 'garlic', 'flavours']
rows = []
for e in evals:
    if e['iteration'] >= 2:
        r = {x['ingredient']: x['fraction'] for x in e['recipe']}
        r['iter'] = e['iteration']
        r['y'] = e['target_dissimilarity']
        rows.append(r)

df = pd.DataFrame(rows).fillna(0).set_index('iter')
good = df.loc[[14, 13, 11, 7]]
bad = df.drop(index=[14, 13, 11, 7])

print("Bounding box of GOOD (Iters 14, 13, 11, 7, all y in [0.1235, 0.1555]):")
for c in cols:
    print(f"  {c:22s}: [{good[c].min():.4f}, {good[c].max():.4f}]")

print("\nWhich bound of GOOD is violated by each BAD iteration?")
for idx, row in bad.sort_values('y').iterrows():
    viol = []
    for c in cols:
        if row[c] < good[c].min() - 1e-6:
            viol.append(f"{c}={row[c]:.4f} < {good[c].min():.4f}")
        elif row[c] > good[c].max() + 1e-6:
            viol.append(f"{c}={row[c]:.4f} > {good[c].max():.4f}")
    print(f"  Iter {idx:2d} (y={row['y']:.4f}): {', '.join(viol)}")
"}
